# Initially generated by GitHub Copilot.
"""Load and iterate over MAM-parsed-plus corpus files."""

import glob
import json
from dataclasses import dataclass, field
from typing import Iterator, Mapping, TYPE_CHECKING

from mb_cmn import mpplus_schema_guard as mpplus_guard
from mb_cmn import paths

if TYPE_CHECKING:
    from mb_author.claim import ClaimRecord

_PLUS_DIR = str(paths.mam_parsed_dir() / "plus")


@dataclass
class Corpus:
    """Loaded plus-corpus data.

    files: full top-level JSON objects from plus/*.json files.
    book39s: all book39 objects collected across those files.
    """

    files: list = field(default_factory=list)
    book39s: list = field(default_factory=list)


@dataclass
class Context:
    """Everything a verifier may need: the plus corpus and survey artifact."""

    corpus: Corpus
    survey: dict  # loaded plus.json from out/tmpl-survey-plus/
    claim_records: Mapping[str, "ClaimRecord"] | None = None


def load_plus_corpus() -> Corpus:
    """Load every plus/*.json file and collect all book39s.

    Must be called with the repo root as the working directory.
    """
    pattern = f"{_PLUS_DIR}/*.json"
    paths = sorted(glob.glob(pattern))
    assert paths, f"No plus JSON files found matching {pattern!r}"
    files = []
    book39s = []
    for path in paths:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        mpplus_guard.assert_no_non_targeted_scrdff_in_plus(data, path)
        files.append(data)
        book39s.extend(data["book39s"])
    return Corpus(files=files, book39s=book39s)


def iter_chapters(corpus: Corpus) -> Iterator[tuple]:
    """Yield (book39, chapter_key, chapter_dict) for every chapter."""
    for book39 in corpus.book39s:
        for ch_key, chapter in book39["chapters"].items():
            yield book39, ch_key, chapter


def iter_verses(corpus: Corpus) -> Iterator[tuple]:
    """Yield (book39, ch_key, verse_key, verse) for every verse."""
    for book39, ch_key, chapter in iter_chapters(corpus):
        for v_key, verse in chapter.items():
            yield book39, ch_key, v_key, verse


def iter_template_objects(node) -> Iterator[dict]:
    """Recursively yield every template object (dict with 'tmpl_name') in node.

    Handles the full range of node types found in the plus corpus:
    - dict with 'tmpl_name': a template object; yield it, recurse into tmpl_params values.
    - list: recurse into each element.
    - str: no templates inside; stop.
    """
    if isinstance(node, dict):
        if "tmpl_name" in node:
            yield node
            for val in node.get("tmpl_params", {}).values():
                yield from iter_template_objects(val)
    elif isinstance(node, list):
        for item in node:
            yield from iter_template_objects(item)


def iter_all_template_objects(corpus: Corpus) -> Iterator[dict]:
    """Yield every template object across the entire plus corpus."""
    for _book39, _ch_key, _v_key, verse in iter_verses(corpus):
        for col in verse:
            yield from iter_template_objects(col)
